package com.bank.tierorder.service;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.logging.Logger;

// Derive symbol order from sorted codes, then topologically sort.
public class TierOrderService {
    private static final Logger log = Logger.getLogger(TierOrderService.class.getName());

    public String deriveSymbolOrder(String[] sortedCodes) {
        Map<Character, List<Character>> adj = new HashMap<>();
        Map<Character, Integer> indeg = new HashMap<>();
        for (String code : sortedCodes)
            for (char c : code.toCharArray()) {
                adj.putIfAbsent(c, new ArrayList<>());
                indeg.putIfAbsent(c, 0);
            }
        for (int i = 0; i + 1 < sortedCodes.length; i++) {
            String a = sortedCodes[i], b = sortedCodes[i + 1];
            int min = Math.min(a.length(), b.length());
            int k = 0;
            while (k < min && a.charAt(k) == b.charAt(k)) k++;
            if (k == min) {
                if (a.length() > b.length()) {       // later word is a strict prefix: invalid
                    log.severe("Invalid dictionary: " + a + " before " + b);
                    return "";
                }
            } else {
                adj.get(a.charAt(k)).add(b.charAt(k)); // first difference gives an edge
                indeg.merge(b.charAt(k), 1, Integer::sum);
            }
        }
        Queue<Character> queue = new LinkedList<>();
        for (Map.Entry<Character, Integer> e : indeg.entrySet())
            if (e.getValue() == 0) queue.add(e.getKey());
        StringBuilder order = new StringBuilder();
        while (!queue.isEmpty()) {
            char c = queue.poll();
            order.append(c);
            for (char next : adj.get(c))
                if (indeg.merge(next, -1, Integer::sum) == 0) queue.add(next);
        }
        if (order.length() != indeg.size()) {
            log.severe("Cycle detected: contradictory ordering");
            return "";
        }
        final String r = order.toString();
        log.info(() -> "Derived symbol order = " + r);
        return r;
    }
}
