package com.bank.tierorder;

import com.bank.tierorder.service.TierOrderService;
import java.util.logging.Logger;

public class TierOrderApplication {
    private static final Logger log = Logger.getLogger(TierOrderApplication.class.getName());

    public static void main(String[] args) {
        TierOrderService service = new TierOrderService();
        String[] sortedCodes = {"ba", "bc", "ac", "cab"};
        String order = service.deriveSymbolOrder(sortedCodes);
        log.info("Recovered tier symbol order: " + order);
    }
}
